let fk : Module.End k V :=
      { toFun := f, map_add' := f.map_add
        map_smul' := fun μ v => by
          have h := f.map_smul (algebraMap k A μ) v
          rw [algebraMap_smul, algebraMap_smul] at h
          exact h }

let T' : Module.End (Module.End A V) V :=
    { toFun := T, map_add' := T.map_add
      map_smul' := fun g v => by
        obtain ⟨μ, hμ⟩ := hEnd' g
        change T (g v) = g (T v)
        rw [hμ, hμ, T.map_smul] }
